	async function copyToClipboard(text) {
		telemetry.track("share_copy", {
			text_len: text ? text.length : 0,
			is_url: text ? text.includes("http") || text.includes("#") : false,
			has_timestamp: text ? text.includes("t=") || text.includes("tab=") : false
		});
		if (typeof GM_setClipboard === "function") try {
			GM_setClipboard(text);
			return true;
		} catch {}
		if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") try {
			await navigator.clipboard.writeText(text);
			return true;
		} catch {}
		try {
			const textarea = document.createElement("textarea");
			textarea.value = text;
			textarea.style.position = "fixed";
			textarea.style.left = "-9999px";
			textarea.style.top = "-9999px";
			textarea.style.opacity = "0";
			document.body.appendChild(textarea);
			textarea.focus();
			textarea.select();
			const success = document.execCommand("copy");
			document.body.removeChild(textarea);
			return success;
		} catch (err) {
			console.error("[clipboard] 复制到剪贴板失败:", err);
			return false;
		}
	}
