				if (e.target.closest(".tm-control-buttons, .tm-button-container, .tm-control-button, .tm-close-button, .tm-settings-button, .tm-settings-panel")) return;
				const togglePlayPause = () => {
					if (!this.playerCore.targetVideo) return;
					if (this.playerCore.targetVideo.paused) this.playerCore.targetVideo.play();
					else {
						this.playerCore.targetVideo.pause();
						if (this.controlManager) this.controlManager.showPauseIndicator();
					}
					if (this.controlManager) this.controlManager.updatePlayPauseButton();
				};
