		getTranslateForIndex(index) {
			return this.config.width / 2 - (index + .5) * this.slotWidth;
		}
		initAudioContext() {
			if (this.audioCtx) return;
			try {
				const AudioCtx = window.AudioContext || window.webkitAudioContext;
				if (AudioCtx) this.audioCtx = new AudioCtx();
			} catch {}
		}
		playHapticSound(type = "tick") {
			if (!this.config.enableSound) return;
			try {
				this.initAudioContext();
				if (this.audioCtx && this.audioCtx.state === "suspended") this.audioCtx.resume().catch(() => {});
				if (!this.audioCtx) return;
				const osc = this.audioCtx.createOscillator();
				const gain = this.audioCtx.createGain();
				const t = this.audioCtx.currentTime;
				if (type === "tick") {
					osc.type = "sine";
					osc.frequency.setValueAtTime(1050, t);
					gain.gain.setValueAtTime(.04, t);
					gain.gain.exponentialRampToValueAtTime(.001, t + .02);
					osc.connect(gain);
					gain.connect(this.audioCtx.destination);
					osc.start(t);
					osc.stop(t + .025);
				} else if (type === "click") {
					osc.type = "sine";
					osc.frequency.setValueAtTime(840, t);
					osc.frequency.exponentialRampToValueAtTime(420, t + .03);
					gain.gain.setValueAtTime(.05, t);
					gain.gain.exponentialRampToValueAtTime(.001, t + .03);
					osc.connect(gain);
					gain.connect(this.audioCtx.destination);
					osc.start(t);
					osc.stop(t + .035);
				}
			} catch {}
		}
