					updateStatus(err.message ? `同步失败: ${err.message}` : "同步失败", "error");
					syncMergeBtn.innerHTML = `${ICON_CLOUD_SYNC} <span>${__("webdavSyncMerge") || "智能合并同步"}</span>`;
