					updateStatus(err.message ? `下载失败: ${err.message}` : "下载失败", "error");
					downloadBtn.innerHTML = `${ICON_CLOUD_DOWNLOAD} <span>${__("webdavDownloadOverwrite") || "下载覆盖"}</span>`;
					setButtonsDisabled(false);
